              const firstNonEmpty = addedLines.find(line => line.trim() !== '');
              if (!firstNonEmpty || !/^\s*(?:[*+-]|\d+\.)\s+/.test(firstNonEmpty)) return false;
              return addedLines.every(line => 
                /^\s*(?:[*+-]|\d+\.)\s+/.test(line) || 
                /^\s+\S/.test(line) || 
                /^\s*$/.test(line)
              );
            });

          const wrongBranch = pr.base.ref === 'master' && !isDocListOnly;
          core.setOutput('violation', wrongBranch ? 'true' : 'false');
          console.log(`Target branch check: ${wrongBranch ? '❌ FAILED' : '✅ PASSED'}`);
      env:
        PR_JSON: ${{ steps.init.outputs.pr }}
        FILES_JSON: ${{ steps.init.outputs.files }}

    - name: "Check AI Tool Disclosure"
      if: steps.membership.outputs.is_member == 'false'
      uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd #v8.0.0
      id: ai
      with:
        script: |
          const pr = JSON.parse(process.env.PR_JSON);
          const prBody = pr.body || '';
          const aiNoContent = /\[[xX]\]\s*My contribution does not include (any )?AI-generated content/i.test(prBody);
          const aiWithContent = /\[[xX]\]\s*My contribution includes AI-generated content/i.test(prBody);
          const aiMissing = !aiNoContent && !aiWithContent;
          core.setOutput('violation', aiMissing ? 'true' : 'false');
          console.log(`AI disclosure check: ${aiMissing ? '❌ FAILED' : '✅ PASSED'}`);
      env:
        PR_JSON: ${{ steps.init.outputs.pr }}

    - name: "Check Affirmation"
      if: steps.membership.outputs.is_member == 'false'
      uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd #v8.0.0
      id: affirmation
      with:
        script: |
          const pr = JSON.parse(process.env.PR_JSON);
