with.script:
const pr = JSON.parse(process.env.PR_JSON);
const files = JSON.parse(process.env.FILES_JSON);

const isDocListOnly = files.length > 0 && 
  files.every(f => ['REFERENCES.md', 'SOLUTIONS.md'].includes(f.filename)) &&
  files.every(f => {
    if (f.deletions > 0 || f.additions === 0 || !f.patch) return false;
    const addedLines = f.patch.replace(/\r/g, '').split('\n')
      .filter(line => line.startsWith('+') && !line.startsWith('+++'))
      .map(line => line.slice(1));
    if (addedLines.length === 0) return false;
    const firstNonEmpty = addedLines.find(line => line.trim() !== '');
    if (!firstNonEmpty || !/^\s*(?:[*+-]|\d+\.)\s+/.test(firstNonEmpty)) return false;
    return addedLines.every(line => 
      /^\s*(?:[*+-]|\d+\.)\s+/.test(line) || 
      /^\s+\S/.test(line) || 
      /^\s*$/.test(line)
    );
  });

const wrongBranch = pr.base.ref === 'master' && !isDocListOnly;
core.setOutput('violation', wrongBranch ? 'true' : 'false');
console.log(`Target branch check: ${wrongBranch ? '❌ FAILED' : '✅ PASSED'}`);

