        const vulnBuzzwords = /\b(?:sql injection|xss|cross[- ]site scripting|csrf|race condition|business logic vulnerability|idor|ssrf|privilege escalation)\b/ig;
        const buzzwordMatches = (rawBody.match(vulnBuzzwords) || []).length;
        const hasFileOrLineRef = /`[^`]*\.(?:ts|js|html|yml|md)[^`]*`|\bline\s+\d+\b/i.test(rawBody);
        const genericVulnPhrasing = /\bintroduce\s+a\b.{0,60}\bvulnerability\b/i.test(rawBody) || /\ballow(?:s)?\s+(?:an\s+)?attacker(?:s)?\s+to\b/i.test(rawBody);
        if (buzzwordMatches >= 2 && !hasFileOrLineRef && !usesTemplate) {
          addScore(65, `Generic, formulaic vulnerability/challenge suggestion without concrete code reference (${buzzwordMatches} buzzwords)`);
          if (genericVulnPhrasing) {
            addScore(20, "Generic vulnerability-injection phrasing typical of formulaic AI-generated submissions");
          }
        }

        // 14. Formulaic AI-generated vulnerability narrative: boilerplate framing ("introduce a ...
        // vulnerability" / "allows attacker(s) to ...") combined with CWE/CVE citation(s) but zero
        // concrete, verifiable technical detail (no real file/code reference). Genuine proposals citing
        // CWEs nearly always also point at an actual file, function or endpoint; purely abstract
        // "narrative" proposals citing CWEs without any such detail are a strong fabrication smell,
        // regardless of whether the official template was used.
        if (genericVulnPhrasing && cweCveMatches >= 1 && !hasFileOrLineRef) {
          addScore(75, "Formulaic AI-generated vulnerability narrative with CWE citation(s) but no concrete file/code reference");
        }

        const spamRating = Math.max(0, Math.min(100, spamScore));
        core.setOutput('spamRating', spamRating);
        console.log(`===================================`);
        console.log(`Final Spam Score: ${spamRating}/100`);
    env:
      ISSUE_JSON: ${{ steps.init.outputs.issue }}

  - name: "Finalize Compliance Check"
    if: always() && steps.membership.outputs.is_member == 'false'
    uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd #v8.0.0
    id: check
    with:
      script: |
        const issue = JSON.parse(process.env.ISSUE_JSON);
        const author = process.env.AUTHOR;
        const spamRating = parseInt(process.env.SPAM_RATING);
        const isSpam = spamRating >= 75;

        const spamPrefix = isSpam ? '🚨 ' : (spamRating >= 40 ? '⚠️ ' : '✅ ');
        core.setOutput('results', `${spamRating > 0 ? `(${spamPrefix}Spam Score: ${spamRating}/100) - ` : ''}${author}`);

        if (!isSpam) {
          console.log('Issue compliance check passed.');
          return;
        }

        const comment = [
          'Unfortunately, this issue does not meet our guidelines and has been closed:',
          '',
          '- 🚨 **Potential Spam Detected:** _This issue has been identified as potential spam (Rating: ' + spamRating + '/100) based on recurring indicators._ ' +
          'We sincerely appreciate your interest in OWASP Juice Shop, but we must focus our limited maintainer ' +
          'resources on meaningful issues that significantly improve the project. Thank you for your understanding. ' +
          'See our [spam handling guide](https://pwning.owasp-juice.shop/companion-guide/latest/part3/contribution.html#_handling_of_spam_prs) for more details.'
        ].join('\n');

        const labels = ['spam'];

        try {
          await github.rest.issues.addLabels({
            owner: context.repo.owner,
            repo: context.repo.repo,
            issue_number: issue.number,
            labels: labels
          });
        } catch (e) {
          console.log(`Failed to add labels to Issue #${issue.number}: ${e.message}`);
        }

        try {
          await github.rest.issues.createComment({
            owner: context.repo.owner,
            repo: context.repo.repo,
            issue_number: issue.number,
            body: comment
          });
        } catch (e) {
          console.log(`Failed to create comment on Issue #${issue.number}: ${e.message}`);
        }

        try {
          await github.rest.issues.update({
            owner: context.repo.owner,
            repo: context.repo.repo,
            issue_number: issue.number,
            state: 'closed'
          });
        } catch (e) {
          console.log(`Failed to close Issue #${issue.number}: ${e.message}`);
        }

        console.log(`Issue #${issue.number} closed due to spam rating (${spamRating}/100). Applied labels: ${labels.join(', ')}`);
    env:
      ISSUE_JSON: ${{ steps.init.outputs.issue }}
      AUTHOR: ${{ steps.init.outputs.author }}
      SPAM_RATING: ${{ steps.spam.outputs.spamRating }}

  - name: "Block Spammer"
    if: always() && steps.membership.outputs.is_member == 'false' && steps.spam.outputs.spamRating >= 75
    uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd #v8.0.0
    env:
      AUTHOR: ${{ steps.init.outputs.author }}
      ORG_ADMIN_TOKEN: ${{ secrets.ORG_ADMIN_TOKEN }}
    with:
      script: |
        const author = process.env.AUTHOR;
        const orgAdminToken = process.env.ORG_ADMIN_TOKEN;
        if (orgAdminToken) {
          try {
            const response = await fetch(`https://api.github.com/orgs/juice-shop/blocks/${encodeURIComponent(author)}`, {
              method: 'PUT',
              headers: {
                'Authorization': `Bearer ${orgAdminToken}`,
                'Accept': 'application/vnd.github+json',
                'User-Agent': 'actions/github-script'
              }
            });
            if (response.ok) {
              console.log(`User ${author} blocked due to spam.`);
            } else {
              const errorText = await response.text();
              console.log(`Failed to block user ${author}: ${response.status} ${errorText}`);
            }
          } catch (e) {
            console.log(`Failed to block user ${author}: ${e.message}`);
          }
        } else {
          console.log('ORG_ADMIN_TOKEN secret not configured, skipping user block.');
        }

  - name: "Slack Notification"
    if: always() && steps.check.outputs.results
    uses: Gamesight/slack-workflow-status@68bf00d0dbdbcb206c278399aa1ef6c14f74347a #v1.3.0
    with:
      repo_token: ${{ secrets.GITHUB_TOKEN }}
      slack_webhook_url: ${{ secrets.SLACK_WEBHOOK_URL }}
      name: "Issue Compliance: ${{ steps.check.outputs.results }}"

