        // corporate language without any concrete evidence (code snippet, log output or line reference)
        const auditStructure = (bodyWithoutComments.match(/^#{1,3}\s*(?:root cause|impact|proposed fix|suggested solution|current (?:state|behavior)|problem statement)/img) || []).length;
        const vagueCorporateLanguage = /\b(?:robustness|maintainability|scalability|resilience|enhance(?:s|d)?|ensure(?:s)?\s+consistency)\b/i.test(rawBody);
