// Repeated runs of whitespace or markdown/decorative characters (table borders, horizontal
// rules, emoji-based difficulty markers, etc.) are extremely common in well-formed markdown
// and must not be mistaken for gibberish spam.
const repeatedCharMatches = cleanBody.match(/(.)\1{5,}/g) || [];
const decorativeRepeatChar = /[\s\-=_*:|#~.>0-9^]/;
const repeatedCharSpam = repeatedCharMatches.some(m => !decorativeRepeatChar.test(m[0]));
if (rewriteTroll.test(bodyLower) || rewriteTroll.test(titleLower) || repeatedWordSpam.test(cleanBody) || repeatedCharSpam) {
  addScore(60, "Nonsense request / troll or gibberish content");
}

// 11. Hallucinated tech stack claims / GSoC-style inquiries
