  addScore(60, "Raw CSS pasted as entire issue body");
}

// 6. Issue body consists only of a permalink / code reference without context
if (/^juice-shop\/(?:frontend\/src|routes|lib)\/[^\s]+\s+line\s+\d+\s+in\s+[a-f0-9]+\s+/i.test(cleanBody) || (/^https:\/\/github\.com\/juice-shop\/juice-shop\/blob\/[^\s]+$/i.test(cleanBody))) {
  addScore(60, "Code permalink pasted without issue description");
}

// 7. Automated vulnerability scanner / AI security audit reports (structural smell, not tied to a
// specific named tool or wording lifted from any single past report)
const sastDastTools = /\b(semgrep|snyk|sonar(?:qube)?|fortify|checkmarx|veracode|trivy|grype|zap|burp\s*suite|nessus|qualys)\b/i;
if (sastDastTools.test(titleLower) || sastDastTools.test(bodyLower)) {
  addScore(30, "Named SAST/DAST/security scanner tool mentioned in title or body");
}

